-- ============================================================================
-- B5 FOLLOW-ON W4a (typed-case panel modes): hydraulics.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 1
-- route (b), and docs/graded-field-audit/w4a/hydraulics.json. Owner approved D1
-- to D7 as recommended, 2026-09-21 (D2: the panel guard forbids a DEFAULT
-- state that lands on a graded answer; typing the case is the work).
--
-- BEGINNER
--   The pipe, annulus and pump pressures need the capstone mud, which no
--   explorer took, and printed in MPa to 4 dp (100 Pa) against tol 50 Pa; the
--   Herschel-Bulkley yield rule was not taught. W4a adds Your mud boxes (four
--   readings and a density, blank is the case's own mud) to all three explorers,
--   prints pressures in MPa to 6 dp, and teaches the yield rule in beginner m02
--   l04. The brief now names the boxes. Prompt only.
--   PROMPT was: Use the Herschel-Bulkley fit for the pressure calculation, which
--   is what the engine does.
--   PROMPT now: Use the Herschel-Bulkley fit for the pressure calculation, which
--   is what the engine does. Type this mud into the rheology explorer's Your mud
--   boxes: its model view fits it and its pressure chain view prints the four
--   pressures in MPa to six decimals.
--
-- INTERMEDIATE
--   ECD, transport, cuttings and the minimum flow for a 0.80 transport ratio all
--   need the capstone mud. W4a adds the Your mud boxes to the cleaning explorer
--   (the tiles already print at the graded precision). The brief now names the
--   boxes. Prompt only.
--   PROMPT was: (6) the flow rate, in m3/s, that reaches a transport ratio of
--   exactly 0.80 on the horizontal well, which is a solve rather than a run and
--   therefore does not use 0.030.
--   PROMPT now: (6) the flow rate, in m3/s, that reaches a transport ratio of
--   exactly 0.80 on the horizontal well, which is a solve rather than a run and
--   therefore does not use 0.030. Type this mud into the cleaning explorer's
--   Your mud boxes and every view runs it.
--
-- ADVANCED
--   Surge, swab, the closed over open ratio and the speed limit need the
--   capstone mud, and no view printed the open-string swab. W4a adds the Your
--   mud boxes to the surge explorer and an open swab EMW tile. The brief now
--   names the boxes. Prompt only.
--   PROMPT was: which is a solve and therefore does not use 0.75.
--   PROMPT now: which is a solve and therefore does not use 0.75. Type this mud
--   into the surge explorer's Your mud boxes: fields 1 to 5 are its Closed
--   string and open view, and field 6 its window view.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its live value exactly, before and after.
--
-- ATTEMPTS. Prompt copy only: no graded key or tolerance moves, so no attempt
-- can be graded differently and there is no attempts guard.
--
-- GUARDS. Each row must hold EITHER its live prompt (by md5) and fields (exact
-- jsonb) as the W1-state scratch replay has them (it is rewritten), OR its W4a
-- form (left alone). Anything else raises and the whole file rolls back. A
-- file that will write first checks that W1 is applied and refuses without it.
-- Generated by docs/graded-field-audit/w4a_capstones.py. SAFE TO RE-RUN: a
-- second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- hydraulics / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'hydraulics' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w4a hydraulics refused: hydraulics/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '9e504c45bfea038773b48a6004f6201c' and fields = '[{"key": "pl_n", "tol": 5E-7, "unit": "-", "label": "Power law flow behaviour index", "expected": 0.6560455987826389}, {"key": "hb_tau_y_Pa", "tol": 0.0005, "unit": "Pa", "label": "Herschel-Bulkley yield stress", "expected": 2.04161424376}, {"key": "pipe_dp_Pa", "tol": 50, "unit": "Pa", "label": "Pipe pressure loss", "expected": 8990804.931422047}, {"key": "annulus_dp_Pa", "tol": 50, "unit": "Pa", "label": "Annulus pressure loss", "expected": 1531961.9814624505}, {"key": "bit_dp_Pa", "tol": 50, "unit": "Pa", "label": "Bit pressure drop", "expected": 3086064.831211029}, {"key": "pump_pressure_Pa", "tol": 50, "unit": "Pa", "label": "Pump pressure", "expected": 13608831.744095527}]'::jsonb then 'old'
              when md5(prompt) = '0a6d19e01bf7349ba54fdc178778bc67' and fields = '[{"key": "pl_n", "tol": 5E-7, "unit": "-", "label": "Power law flow behaviour index", "expected": 0.6560455987826389}, {"key": "hb_tau_y_Pa", "tol": 0.0005, "unit": "Pa", "label": "Herschel-Bulkley yield stress", "expected": 2.04161424376}, {"key": "pipe_dp_Pa", "tol": 50, "unit": "Pa", "label": "Pipe pressure loss", "expected": 8990804.931422047}, {"key": "annulus_dp_Pa", "tol": 50, "unit": "Pa", "label": "Annulus pressure loss", "expected": 1531961.9814624505}, {"key": "bit_dp_Pa", "tol": 50, "unit": "Pa", "label": "Bit pressure drop", "expected": 3086064.831211029}, {"key": "pump_pressure_Pa", "tol": 50, "unit": "Pa", "label": "Pump pressure", "expected": 13608831.744095527}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'hydraulics' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w4a hydraulics refused: hydraulics/beginner matches neither its live form (prompt md5 9e504c45bfea038773b48a6004f6201c) nor its W4a form (prompt md5 0a6d19e01bf7349ba54fdc178778bc67), with the fields this file was generated against';
  end if;

  -- hydraulics / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'hydraulics' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w4a hydraulics refused: hydraulics/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '3a9c9710b2bd438e102b9074c0be54a2' and fields = '[{"key": "slant_ecd_at_td_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant well ECD at total depth", "expected": 1382.2893336895256}, {"key": "slant_min_annular_velocity_ms", "tol": 0.00005, "unit": "m/s", "label": "Worst annular velocity", "expected": 1.1756560409748478}, {"key": "horizontal_ecd_at_td_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Horizontal well ECD", "expected": 1441.9531576465401}, {"key": "horizontal_min_transport_ratio", "tol": 0.00005, "unit": "-", "label": "Worst transport ratio", "expected": 0.8328468755463043}, {"key": "horizontal_worst_cuttings_conc_pct", "tol": 0.00005, "unit": "percent", "label": "Worst cuttings concentration", "expected": 0.7326199737252664}, {"key": "horizontal_min_flow_tr080_m3s", "tol": 0.000005, "unit": "m3/s", "label": "Flow rate for a 0.80 ratio", "expected": 0.024178302356402937}]'::jsonb then 'old'
              when md5(prompt) = 'a830cb512338973b1a906bfb42a42b0f' and fields = '[{"key": "slant_ecd_at_td_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant well ECD at total depth", "expected": 1382.2893336895256}, {"key": "slant_min_annular_velocity_ms", "tol": 0.00005, "unit": "m/s", "label": "Worst annular velocity", "expected": 1.1756560409748478}, {"key": "horizontal_ecd_at_td_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Horizontal well ECD", "expected": 1441.9531576465401}, {"key": "horizontal_min_transport_ratio", "tol": 0.00005, "unit": "-", "label": "Worst transport ratio", "expected": 0.8328468755463043}, {"key": "horizontal_worst_cuttings_conc_pct", "tol": 0.00005, "unit": "percent", "label": "Worst cuttings concentration", "expected": 0.7326199737252664}, {"key": "horizontal_min_flow_tr080_m3s", "tol": 0.000005, "unit": "m3/s", "label": "Flow rate for a 0.80 ratio", "expected": 0.024178302356402937}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'hydraulics' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w4a hydraulics refused: hydraulics/intermediate matches neither its live form (prompt md5 3a9c9710b2bd438e102b9074c0be54a2) nor its W4a form (prompt md5 a830cb512338973b1a906bfb42a42b0f), with the fields this file was generated against';
  end if;

  -- hydraulics / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'hydraulics' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w4a hydraulics refused: hydraulics/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'a2c9a10b94b585cc19a1883dc09d6284' and fields = '[{"key": "slant_surge_dp_closed_Pa", "tol": 50, "unit": "Pa", "label": "Slant closed-string surge pressure", "expected": 1147176.908236135}, {"key": "slant_surge_emw_closed_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant closed surge EMW", "expected": 1366.6440330130283}, {"key": "slant_swab_emw_open_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant open-string swab EMW", "expected": 1281.0694196662196}, {"key": "closed_over_open_dp_ratio", "tol": 0.00005, "unit": "-", "label": "Closed over open pressure", "expected": 1.1981335138884341}, {"key": "horizontal_surge_emw_closed_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Horizontal closed surge EMW", "expected": 1411.1350006312582}, {"key": "slant_max_trip_speed_ms", "tol": 0.00005, "unit": "m/s", "label": "Maximum trip speed in the window", "expected": 1.0880403500952598}]'::jsonb then 'old'
              when md5(prompt) = 'ebc70c0adbd623b507918564de7f9bde' and fields = '[{"key": "slant_surge_dp_closed_Pa", "tol": 50, "unit": "Pa", "label": "Slant closed-string surge pressure", "expected": 1147176.908236135}, {"key": "slant_surge_emw_closed_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant closed surge EMW", "expected": 1366.6440330130283}, {"key": "slant_swab_emw_open_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant open-string swab EMW", "expected": 1281.0694196662196}, {"key": "closed_over_open_dp_ratio", "tol": 0.00005, "unit": "-", "label": "Closed over open pressure", "expected": 1.1981335138884341}, {"key": "horizontal_surge_emw_closed_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Horizontal closed surge EMW", "expected": 1411.1350006312582}, {"key": "slant_max_trip_speed_ms", "tol": 0.00005, "unit": "m/s", "label": "Maximum trip speed in the window", "expected": 1.0880403500952598}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'hydraulics' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w4a hydraulics refused: hydraulics/advanced matches neither its live form (prompt md5 a2c9a10b94b585cc19a1883dc09d6284) nor its W4a form (prompt md5 ebc70c0adbd623b507918564de7f9bde), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W4a form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w4a hydraulics: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024a/b) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'rodpump' and tier = 'beginner' and active and md5(prompt) = '27fc6852586864af77f23cdbbf2deacc')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'petrophysics' and c.tier = 'advanced' and c.active and f->>'key' = 'sw_waterleg_mean'
                   and (f->>'tol')::float8 = 0.005) then
    raise exception 'w4a hydraulics refused: W1 (20261024a/b) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Six numbers, on a mud you have not seen. It reads 52 at 600 rpm, 33 at 300, 6 at 6 rpm and 5 at 3 rpm, at a density of 1320 kg/m3. That is NOT either of the two muds the lessons run on, and the same new mud is used at all three tiers. Report: (1) the POWER LAW flow behaviour index n for that mud, which is not the Herschel-Bulkley n; (2) the HERSCHEL-BULKLEY yield stress in pascals, which is not the Bingham yield point and is less than half of it; then, circulating that mud down the SLANT well at 0.030 m3/s, which is not one of the three rates the lessons use, with the fixture''s own hole geometry, the shared string, a discharge coefficient of 0.95 and no surface loss, report (3) the total PIPE pressure loss, (4) the total ANNULUS pressure loss, (5) the BIT pressure drop, and (6) the PUMP pressure. Use the Herschel-Bulkley fit for the pressure calculation, which is what the engine does. Type this mud into the rheology explorer''s Your mud boxes: its model view fits it and its pressure chain view prints the four pressures in MPa to six decimals. All four pressures are in PASCALS, and field 6 must equal the sum of fields 3, 4 and 5 exactly.'
     where app_slug = 'hydraulics' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w4a hydraulics refused: hydraulics/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '0a6d19e01bf7349ba54fdc178778bc67' and fields = '[{"key": "pl_n", "tol": 5E-7, "unit": "-", "label": "Power law flow behaviour index", "expected": 0.6560455987826389}, {"key": "hb_tau_y_Pa", "tol": 0.0005, "unit": "Pa", "label": "Herschel-Bulkley yield stress", "expected": 2.04161424376}, {"key": "pipe_dp_Pa", "tol": 50, "unit": "Pa", "label": "Pipe pressure loss", "expected": 8990804.931422047}, {"key": "annulus_dp_Pa", "tol": 50, "unit": "Pa", "label": "Annulus pressure loss", "expected": 1531961.9814624505}, {"key": "bit_dp_Pa", "tol": 50, "unit": "Pa", "label": "Bit pressure drop", "expected": 3086064.831211029}, {"key": "pump_pressure_Pa", "tol": 50, "unit": "Pa", "label": "Pump pressure", "expected": 13608831.744095527}]'::jsonb) from public.academy_capstones where app_slug = 'hydraulics' and tier = 'beginner' and active) is not true then
    raise exception 'w4a hydraulics refused: hydraulics/beginner does not read back as its W4a form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Six numbers on the same new mud as the Associate capstone: 52, 33, 6 and 5 at 1320 kg/m3, at a flow rate of 0.030 m3/s for fields 1 to 5. Report: (1) the EQUIVALENT CIRCULATING DENSITY at total depth on the SLANT well; (2) the worst (minimum) ANNULAR VELOCITY on that same run, which depends on the flow rate and the geometry alone and therefore not on the mud at all; (3) the equivalent circulating density at total depth on the HORIZONTAL well, which will be LARGER than field 1 even though that well is shallower in measured depth, because the equivalent circulating density divides by TRUE VERTICAL depth; (4) the worst TRANSPORT RATIO on the horizontal well; (5) the worst CUTTINGS CONCENTRATION on the horizontal well as a PERCENTAGE; and (6) the flow rate, in m3/s, that reaches a transport ratio of exactly 0.80 on the horizontal well, which is a solve rather than a run and therefore does not use 0.030. Type this mud into the cleaning explorer''s Your mud boxes and every view runs it.'
