    if v_count <> 1 then raise exception 'w4a hydraulics refused: hydraulics/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'a830cb512338973b1a906bfb42a42b0f' and fields = '[{"key": "slant_ecd_at_td_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant well ECD at total depth", "expected": 1382.2893336895256}, {"key": "slant_min_annular_velocity_ms", "tol": 0.00005, "unit": "m/s", "label": "Worst annular velocity", "expected": 1.1756560409748478}, {"key": "horizontal_ecd_at_td_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Horizontal well ECD", "expected": 1441.9531576465401}, {"key": "horizontal_min_transport_ratio", "tol": 0.00005, "unit": "-", "label": "Worst transport ratio", "expected": 0.8328468755463043}, {"key": "horizontal_worst_cuttings_conc_pct", "tol": 0.00005, "unit": "percent", "label": "Worst cuttings concentration", "expected": 0.7326199737252664}, {"key": "horizontal_min_flow_tr080_m3s", "tol": 0.000005, "unit": "m3/s", "label": "Flow rate for a 0.80 ratio", "expected": 0.024178302356402937}]'::jsonb) from public.academy_capstones where app_slug = 'hydraulics' and tier = 'intermediate' and active) is not true then
    raise exception 'w4a hydraulics refused: hydraulics/intermediate does not read back as its W4a form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Six numbers on the same new mud again: 52, 33, 6 and 5 at 1320 kg/m3. The trip speed is 0.75 m/s for fields 1 to 5, which is not one of the three the lessons use. Report: (1) the SURGE PRESSURE on the SLANT well with a CLOSED string, in pascals; (2) the SURGE equivalent mud weight from that same run; (3) the SWAB equivalent mud weight on the same well with an OPEN string, which is BELOW the mud weight and is two changes from field 2 at once; (4) the ratio of the CLOSED pressure to the OPEN pressure on that well, which is greater than one; (5) the surge equivalent mud weight on the HORIZONTAL well with a closed string, which is much larger than field 2 because the equivalent mud weight divides by TRUE VERTICAL depth; and (6) the MAXIMUM TRIP SPEED, in m/s, that the slant well allows with a CLOSED string given a fracture equivalent mud weight of 1400 kg/m3 and a pore equivalent mud weight of 1260 kg/m3, which is a solve and therefore does not use 0.75. Type this mud into the surge explorer''s Your mud boxes: fields 1 to 5 are its Closed string and open view, and field 6 its window view.'
     where app_slug = 'hydraulics' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w4a hydraulics refused: hydraulics/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'ebc70c0adbd623b507918564de7f9bde' and fields = '[{"key": "slant_surge_dp_closed_Pa", "tol": 50, "unit": "Pa", "label": "Slant closed-string surge pressure", "expected": 1147176.908236135}, {"key": "slant_surge_emw_closed_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant closed surge EMW", "expected": 1366.6440330130283}, {"key": "slant_swab_emw_open_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Slant open-string swab EMW", "expected": 1281.0694196662196}, {"key": "closed_over_open_dp_ratio", "tol": 0.00005, "unit": "-", "label": "Closed over open pressure", "expected": 1.1981335138884341}, {"key": "horizontal_surge_emw_closed_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Horizontal closed surge EMW", "expected": 1411.1350006312582}, {"key": "slant_max_trip_speed_ms", "tol": 0.00005, "unit": "m/s", "label": "Maximum trip speed in the window", "expected": 1.0880403500952598}]'::jsonb) from public.academy_capstones where app_slug = 'hydraulics' and tier = 'advanced' and active) is not true then
    raise exception 'w4a hydraulics refused: hydraulics/advanced does not read back as its W4a form';
  end if;

  raise notice 'w4a hydraulics: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
